    # Find the regularly spaced separator rows and columns.
    def lines(axis):
        n = h if axis == 0 else w
        vals = [grid[i][0] if axis == 0 else grid[0][i] for i in range(n)]
        candidates = []
        for color in set(vals):
            inds = [i for i, v in enumerate(vals) if v == color]
            if len(inds) >= 3:
                diffs = [b-a for a, b in zip(inds, inds[1:])]
                step = max(set(diffs), key=diffs.count)
                if diffs.count(step) >= len(diffs)-1:
                    candidates.append((len(inds), color, step, inds))
        return max(candidates)[3] if candidates else []

    # The separators are the rows/columns carrying the grid-line color.
    row_lines = lines(0)
    col_lines = lines(1)
    if len(row_lines) < 2 or len(col_lines) < 2:
        return grid
    base = max(set(sum(grid, [])), key=sum(grid, []).count)
    out = [[base for _ in range(len(col_lines)-1)] for _ in range(len(row_lines)-1)]
