def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows/columns are the regularly spaced lines; the output
    # records the colors at their intersections, with ordinary line color
    # replaced by the tile's interior color.
    def find_lines(axis):
        n = h if axis == 0 else w
        # A separator line has a repeated color across most of its length.
        scores = []
        for i in range(n):
            line = grid[i] if axis == 0 else [grid[r][i] for r in range(h)]
            from collections import Counter
            cnt = Counter(line)
            scores.append(max(cnt.values()))
        best = None
        for step in range(2, n):
            for start in range(min(step, n)):
                seq = list(range(start, n, step))
                if len(seq) < 3:
                    continue
                score = sum(scores[i] for i in seq)
                if best is None or score > best[0]:
                    best = score, step, start
        if best is None:
            return []
        _, step, start = best
        return list(range(start, n, step))

    rs = find_lines(0)
    cs = find_lines(1)
    if len(rs) < 2 or len(cs) < 2:
        return grid

    # Tile fill is the most frequent non-separator color.
    from collections import Counter
    fill_counts = Counter()
    for r in range(h):
        for c in range(w):
            if r not in rs and c not in cs:
                fill_counts[grid[r][c]] += 1
    fill = fill_counts.most_common(1)[0][0]

    out = []
    for r in rs[:-1]:
        row = []
        for c in cs[:-1]:
            v = grid[r][c]
            row.append(fill if v == grid[rs[0]][cs[0]] else v)
        out.append(row)
    return out
